/** Markup for "SAT solving". */
(function (root, factory) {
  const api = factory(root);
  if (typeof module !== 'undefined' && module.exports) module.exports = api;
  if (root) root.SatTemplate = api;
}(typeof window !== 'undefined' ? window : null, function (scope) {
  'use strict';

  /* Every family is generated by M20's `instance-generators.js`, so the
     instances here are the ones the NP milestone already reasons about. */
  const FAMILIES = {
    pigeonhole: { label: 'pigeonhole — n + 1 pigeons into n holes', min: 3, max: 7, value: 5,
      unit: 'holes',
      about: 'unsatisfiable for a reason a human states in one sentence, and exponential for '
        + 'every solver built on resolution' },
    random: { label: 'random 3-SAT at the satisfiability threshold', min: 10, max: 70,
      value: 30, unit: 'variables',
      about: 'clauses at 4.26 per variable, where half the instances are satisfiable and both '
        + 'answers are hard' },
    planted: { label: 'random 3-SAT with a solution planted in it', min: 20, max: 80,
      value: 60, unit: 'variables',
      about: 'satisfiable by construction, and the case where the simpler solver wins' },
    horn: { label: 'Horn clauses — at most one positive literal each', min: 10, max: 60,
      value: 40, unit: 'variables',
      about: 'the polynomial fragment: unit propagation alone decides it, with no search' }
  };

  const CONTROLS = [
    { id: 'sat-family', kind: 'select', label: 'instance family', value: 'pigeonhole',
      options: Object.keys(FAMILIES).map(function (id) {
        return { value: id, label: FAMILIES[id].label };
      }) },
    { id: 'sat-size', kind: 'range', label: 'size', value: 5, min: 3, max: 80, step: 1 },
    { id: 'sat-conflict', kind: 'range', label: 'draw the implication graph at conflict',
      value: 1, min: 1, max: 12, step: 1 }
  ];

  const METRICS = [
    { id: 'sat-verdict', label: 'Verdict', note: 'and the evidence it carries' },
    { id: 'sat-decisions', label: 'Decisions', note: 'branches the search had to guess' },
    { id: 'sat-conflicts', label: 'Conflicts, and clauses learned',
      note: 'each one prunes a region for good' },
    { id: 'sat-props', label: 'Propagations', note: 'assignments forced rather than guessed' },
    { id: 'sat-visits', label: 'Clause visits',
      note: 'the work two-watched literals is minimising' },
    { id: 'sat-evidence', label: 'Evidence checked',
      note: 'by code with no search in it at all' }
  ];

  function render() {
    return '<div class="grid-2">' +
      scope.ControlPanel.markup({ title: 'Decide, propagate, learn, backjump',
        controls: CONTROLS }) +
      '<div class="card"><div class="card-header">The instance</div>' +
      '<div class="card-body"><pre class="code-block" id="sat-formula"></pre>' +
      '<p class="note" id="sat-formula-caption"></p></div></div>' +
      '</div>' +
      scope.MetricGrid.markup(METRICS) +
      graphCard() +
      card('sat-trail', 'The trail at that conflict, in the order it was built',
        ['Literal', 'Level', 'How', 'The clause that forced it']) +
      card('sat-families', 'Where clause learning pays, and where it does not',
        ['Family', 'Verdict', 'CDCL decisions', 'DPLL nodes', 'Search tree ratio',
          'What the family shows']) +
      chartCard() +
      card('sat-parts', 'The five ideas in a modern solver, and what each one buys',
        ['Part', 'What it does', 'What it costs', 'What breaks without it']);
  }

  function graphCard() {
    return '<div class="card" style="margin-top:.875rem">' +
      '<div class="card-header">The implication graph at the conflict, and the cut</div>' +
      '<div class="card-body"><div id="sat-graph" class="mermaid-host"></div>' +
      '<p class="note" id="sat-graph-note"></p></div></div>';
  }

  function chartCard() {
    return '<div class="card" style="margin-top:.875rem">' +
      '<div class="card-header">Search tree size against instance size, both solvers</div>' +
      '<div class="card-body"><div id="sat-chart" class="chart-host"></div>' +
      '<div id="sat-legend" class="legend-host"></div>' +
      '<p class="note" id="sat-chart-note"></p></div></div>';
  }

  function card(id, title, columns) {
    return '<div class="card" style="margin-top:.875rem">' +
      '<div class="card-header">' + title + '</div>' +
      '<div class="card-body"><table class="ref-table" id="' + id + '"><thead><tr>' +
      columns.map(function (name) { return '<th>' + name + '</th>'; }).join('') +
      '</tr></thead><tbody></tbody></table>' +
      '<p class="note" id="' + id + '-caption"></p></div></div>';
  }

  return { render: render, controls: CONTROLS, metrics: METRICS, FAMILIES: FAMILIES };
}));
